L47_1 = "아하, 솔로카오 초콜릿이라고 부르는군요. 아무래도 옳게 찾아온 모양이네요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "へえ、ソロカオチョコレートと言うのですね。どうやらここで間違いないようですね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "A-ha! So, it's called Solocao. It seems we have come to the right place."
L46_1.m_Talk_ENG = L47_1
L47_1 = "啊哈，原來這就是所謂的獨株可可巧克力啊，看來我找對地方了。"
L46_1.m_Talk_TWN = L47_1
