L6_1.m_Pos = "L"
L7_1 = "저희는 디저트 만들 때 쓸 초콜릿을 구하려고 그라운드 원에서 여기까지 왔거든요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "私たちはデザートを作る時に使うチョコレートを探してグラウンド・ワンからここまで来たんです。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "We came all the way from Ground One to find chocolate we can use in our desserts."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我們是為了找製作甜點用的巧克力，從G1來到這裡的。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "我们是为了找制作甜点用的巧克力，从G1来到这里的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "We came all the way from Ground One to find chocolate we can use in our desserts."
